from datetime import date, timedelta
import calendar

_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _add_months(year, month, delta):
    index = year * 12 + (month - 1) + delta
    return index // 12, index % 12 + 1


def _nth_weekday(year, month, n, weekday):
    last_day = calendar.monthrange(year, month)[1]
    if n == -1:
        current = date(year, month, last_day)
        return current - timedelta(days=(current.weekday() - weekday) % 7)
    first = date(year, month, 1)
    day = 1 + (weekday - first.weekday()) % 7 + (n - 1) * 7
    if day > last_day:
        return None
    return date(year, month, day)


def recur(start: str, rule: str, count: int) -> list[str]:
    year, month, day = (int(part) for part in start.split("-"))
    start_date = date(year, month, day)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    found = []

    if kind == "DAILY":
        current = start_date
        for _ in range(count):
            found.append(current.isoformat())
            current += timedelta(days=interval)
        return found

    if kind == "WEEKLY":
        weekdays = sorted(_WEEKDAYS[code] for code in parts[2].split(","))
        week_monday = start_date - timedelta(days=start_date.weekday())
        step = 0
        while len(found) < count:
            monday = week_monday + timedelta(weeks=step * interval)
            for weekday in weekdays:
                current = monday + timedelta(days=weekday)
                if current >= start_date:
                    found.append(current.isoformat())
                    if len(found) == count:
                        break
            step += 1
        return found

    if kind == "MONTHLY" and len(parts) == 3:
        day_of_month = int(parts[2])
        step = 0
        while len(found) < count:
            active_year, active_month = _add_months(year, month, step * interval)
            last_day = calendar.monthrange(active_year, active_month)[1]
            if day_of_month == -1:
                current = date(active_year, active_month, last_day)
            elif day_of_month <= last_day:
                current = date(active_year, active_month, day_of_month)
            else:
                current = None
            if current is not None and current >= start_date:
                found.append(current.isoformat())
            step += 1
        return found

    if kind == "MONTHLY":
        nth = int(parts[2])
        weekday = _WEEKDAYS[parts[3]]
        step = 0
        while len(found) < count:
            active_year, active_month = _add_months(year, month, step * interval)
            current = _nth_weekday(active_year, active_month, nth, weekday)
            if current is not None and current >= start_date:
                found.append(current.isoformat())
            step += 1
        return found

    month_text, day_text = parts[2].split("-")
    target_month, target_day = int(month_text), int(day_text)
    step = 0
    while len(found) < count:
        try:
            current = date(year + step * interval, target_month, target_day)
        except ValueError:
            current = None
        if current is not None and current >= start_date:
            found.append(current.isoformat())
        step += 1
    return found
